// Pure mathematical mapping (p: Vec3, t?: number) => Vec3
const customRipple = (p: Vec3, t: number = 1.0) => {
    const r = Math.sqrt(p.x * p.x + p.y * p.y);
    const wave = Math.sin(r * 4.0 - t * Math.PI) * 0.3 * t;
    return new Vec3(p.x + (p.x / (r || 1)) * wave, p.y + (p.y / (r || 1)) * wave, p.z);
};

