});

import { ISpatialField, Vec3 } from "retiam";

export class GravitationalDipoleField implements ISpatialField {
    constructor(public poleDistance: number = 2.0, public strength: number = 0.5) {}

    public evaluate(p: Vec3, t: number = 1.0): Vec3 {
        const d1 = Math.hypot(p.x - this.poleDistance, p.y) + 0.1;
        const d2 = Math.hypot(p.x + this.poleDistance, p.y) + 0.1;
        const pullX = (this.strength * t) * (1 / (d1 * d1) - 1 / (d2 * d2));
        return new Vec3(p.x - pullX, p.y, p.z);
    }
}

export interface SubdivisionOptions {
    /** Fixed subdivisions per segment (e.g. 30) */
    subdivisions?: number;
    /** Maximum Euclidean length of any sub-segment in coordinate units (e.g. 0.05 for ultra-smooth lines) */
    maxSegmentLength?: number;
    /** Flatness or error tolerance threshold */
    tolerance?: number;
    /** Normalized accuracy multiplier [0.1..10.0] (default 1.0) */
    accuracy?: number;
}

// Subdivides straight segments into dense intermediate vertices using count or SubdivisionOptions
SubdivisionEngine.subdividePolyline(points: Vec3[], options?: number | SubdivisionOptions): Vec3[];
SubdivisionEngine.subdivideClosedPolygon2D(points: Vec2[], options?: number | SubdivisionOptions): Vec2[];

export abstract class VectorEntity extends Entity {
    /** Subdivides geometry so straight edges bend into curves (supports count or SubdivisionOptions) */
    public prepareForNonlinearTransform(options?: number | SubdivisionOptions): this;

    /** Warps entity and all children using an ISpatialField or mapping callback */
    public applyField(field: ISpatialField | SpatialMappingFunction, t: number = 1.0): this;

    /** Warps entity using a continuous homotopy H(p, t) */
    public applyHomotopy(homotopy: HomotopyFunction, t: number): this;

    /** Warps entity using a complex analytic function f(z) */
    public applyComplexFunction(fn: (z: { re: number; im: number }) => { re: number; im: number }, alpha: number = 1.0): this;

    /** Restores base undeformed geometry */
    public resetDeformation(): this;
}

