import { Scene, NumberPlane, MeshSprite, HomotopyAnimation, Field, Rate, BLACK } from "retiam";

export class DeformedImageScene extends Scene {
    public async run() {
        this.ALWAYS_UPDATE = true;
        this.setBackgroundColor(BLACK);

        const xRange: [number, number] = [-4.8, 4.8];
        const yRange: [number, number] = [-2.7, 2.7];

        // 1. Create Deformable MeshSprite (Green leaves with dewdrops)
        const image = new MeshSprite({
            source: "/res/media/image.jpg",
            xRange: xRange,
            yRange: yRange,
            gridResolution: [48, 27],
            opacity: 0.95
        });

        // 2. Create Coordinate Grid
        const plane = new NumberPlane({
            xRange: [xRange[0], xRange[1], 0.6],
            yRange: [yRange[0], yRange[1], 0.6],
            maxSegmentLength: 0.05,
            accuracy: 8
        });

        image.z_index = -0.01;
        plane.z_index = 0.01;
        this.add(image);
        this.add(plane);

        const targets = [plane, image];

        // 3. Continuous Wave and Conformal Morphing Loop
        while (true) {
            await this.play(new HomotopyAnimation(targets, Field.wave({ amplitude: 0.35, frequency: 2.2 }), {
                duration: 3000,
                rate_func: Rate.easeInOut(3)
            }));
            await this.wait(1000);

            await this.play(new HomotopyAnimation(targets, Field.swirl({ strength: 0.9, radius: 3.0 }), {
                duration: 3000,
                rate_func: Rate.smooth()
            }));
            await this.wait(1000);
        }
    }
}

