import { Scene, NumberPlane, MeshSprite, Sprite, HomotopyAnimation, Field, Rate, Vec3, BLACK } from "retiam";

export class DeformedTextureScene extends Scene {
    public async run() {
        this.ALWAYS_UPDATE = true;
        this.setBackgroundColor(BLACK);

        const widthSpan = 9.6;
        const heightSpan = 4.8;

        const earthSprite = new Sprite("/res/media/earth.jpg");
        const earthMesh = new MeshSprite({
            source: earthSprite,
            xRange: [-widthSpan / 2, widthSpan / 2],
            yRange: [-heightSpan / 2, heightSpan / 2],
            gridResolution: [48, 24],
            opacity: 0.95
        });

        const plane = new NumberPlane({
            xRange: [-widthSpan / 2, widthSpan / 2, 0.6],
            yRange: [-heightSpan / 2, heightSpan / 2, 0.6],
            accuracy: 8
        });

        this.add(earthMesh);
        this.add(plane);

        const targets = [plane, earthMesh];

        // Sinusoidal equal-area cartographic projection: x' = x * cos(y)
        const sinusoidalMap = (p: Vec3, t: number = 1.0): Vec3 => {
            const latFactor = Math.cos((p.y / (heightSpan / 2)) * (Math.PI / 2.2));
            const targetX = p.x * latFactor;
            return new Vec3(p.x + (targetX - p.x) * t, p.y, p.z);
        };

        await this.play(new HomotopyAnimation(targets, sinusoidalMap, { duration: 3200 }));
    }
}

