    yRange: [-4, 4, 0.4],
    maxSegmentLength: 0.04
});
scene.add(plane);

// Conformal map: sin(x + iy) = sin(x)cosh(y) + i cos(x)sinh(y)
const conformalField = Field.conformal((z) => {
    const scale = 1.4;
    const x = z.re * scale;
    const y = z.im * scale;
    const sinX = Math.sin(x);
    const cosX = Math.cos(x);
    const coshY = Math.cosh(Math.max(-2, Math.min(2, y)));
    const sinhY = Math.sinh(Math.max(-2, Math.min(2, y)));

    return {
        re: z.re + 0.28 * sinX * coshY,
        im: z.im + 0.28 * cosX * sinhY
    };
});

await scene.play(new HomotopyAnimation(plane, conformalField, {
    duration: 3500,
    rate_func: Rate.easeInOut(2.5)
}));

